import{_ as e,o as l,c as r,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const M=JSON.parse('{"title":"CQM 量子引力讨论：两个候选与 FG","description":"","frontmatter":{},"headers":[],"relativePath":"D013_量子引力讨论.md","filePath":"D013_量子引力讨论.md"}'),s={name:"D013_量子引力讨论.md"};function o(a,t,d,g,i,C){return l(),r("div",null,[...t[0]||(t[0]=[n('<div><h1 id="cqm-量子引力讨论-两个候选与-fg" tabindex="-1">CQM 量子引力讨论：两个候选与 FG <a class="header-anchor" href="#cqm-量子引力讨论-两个候选与-fg" aria-label="Permalink to &quot;CQM 量子引力讨论：两个候选与 FG&quot;">​</a></h1><p><strong>作者</strong>：ruster</p><blockquote><p><strong>本文的立场</strong>：<strong>物质的质是作为其潜在而存在的</strong>——不需要假设质本身在叠加、在涨落。CQM <strong>不另立“量子引力”层</strong>：<strong>FG 就是 FG</strong>——无量纲不确定性关系、固有时流速涨落、角亏量子涨落与同步算符的紧化作用就是它的内容。<strong>体系采用候选二</strong>（禁闭内部只是 QCD），故这些内容落在 FG，而不在禁闭内部（§三、§四）。</p><p>相关文档：<code>07 精细引力（FG）/FG_核心理论.md</code> §3.1（无量纲不确定性关系与固有时流速）、<code>01 核心理论/CQM_核心_因果网络同步理论.md</code>（同步与固有时流速）、<code>01 核心理论/CQM_核心_朗兰兹分层共振与相变量子.md</code> §0（SU(5) 由物质自组织锁定）、<code>01 核心理论/CQM_核心_唯物主义群论.md</code> 引言（群＝物质自组织中的组织约束）、<code>归档/CQM_引力_量子引力集成.md</code>（候选一的完整表述）。</p></blockquote><hr><h2 id="一、出发点-质作为其潜在而存在" tabindex="-1">一、出发点：质作为其潜在而存在 <a class="header-anchor" href="#一、出发点-质作为其潜在而存在" aria-label="Permalink to &quot;一、出发点：质作为其潜在而存在&quot;">​</a></h2><p>CQM 的出发点在别处：<strong>物质的质是作为其潜在而存在的</strong>——不需要假设质本身在叠加、在涨落，这是无中生有。</p><p>其本身显在-潜在的状态上叠加涨落：</p><p>假设一：会叠加涨落但无约束，这样会破坏量变质变律</p><p>假设二：会叠加涨落但有约束，可能经典化为量变质变律</p><p>假设三：不会叠加涨落——这个更好，因为：量经由量子物理会叠加涨落，如果质也叠加涨落，那么量变本身无法定义，所以假设一和二都破坏量变质变律；再者事物之间存在普遍的联系，质之间也存在普遍联系，因此量变质变也不存在质变断裂</p><p>由此有一个更细的分叉：<strong>量子引力的内容落在哪一层</strong>。本文比较两个候选：</p><ul><li><strong>候选一</strong>：禁闭内部<strong>是</strong>量子引力；</li><li><strong>候选二</strong>：禁闭内部<strong>只是 QCD</strong>，量子引力另有其所。</li></ul><p>“量子引力”这一名目的所指对两者都成立：它要说明的是时空与引力由何而来，其现实化的产物是<strong>时空同步</strong>与<strong>引力</strong>。两个候选的分歧在于——量子引力的内容落在哪一层。</p><h2 id="二、候选一-禁闭内部是量子引力" tabindex="-1">二、候选一：禁闭内部是量子引力 <a class="header-anchor" href="#二、候选一-禁闭内部是量子引力" aria-label="Permalink to &quot;二、候选一：禁闭内部是量子引力&quot;">​</a></h2><p><strong>内容</strong>：量子引力的物理实在位于单个质子／中子的禁闭内部。FG 的那个<strong>无量纲</strong>不确定性关系，在量子引力这一层反映的不是固有时流速，而是<strong>因果序</strong>一类的结构。</p><p><strong>无量纲不确定性关系的两处读法</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">读法</th><th style="text-align:left;">形式</th><th style="text-align:left;">变量</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FG 侧</strong>（§3.1）</td><td style="text-align:left;">$\\Delta u\\cdot\\Delta v_{\\tau}\\geq ☯/2$</td><td style="text-align:left;">$u=\\ln r_{\\rm coupling}$（耦合空间坐标，无量纲）、$v_{\\tau}=d\\tau/dt$（固有时流速，无量纲）、$p_u=v_{\\tau}/☯$，$☯$ 为相变量子</td></tr><tr><td style="text-align:left;"><strong>量子引力侧</strong>（候选一）</td><td style="text-align:left;">$[\\hat u,\\hat p_u]=i$，其五个等价方面之一</td><td style="text-align:left;">以因果序的方向叠加<strong>替换</strong>固有时流速涨落 $\\Delta v_{\\tau}\\neq0$</td></tr></tbody></table><p>量子引力集成文档把该关系列为五个等价方面：耦合常数的不确定性关系 $[\\hat u,\\hat p_u]=i$、固有时流速涨落 $\\Delta v_{\\tau}\\neq0$、非交换几何 $[x^{\\mu},x^{\\nu}]\\neq0$、量子嘉当矩阵 $A_4^{(q)}$ 的非对角结构、因果序本身的方向叠加。→ 候选一要做的事，是把其中的“<strong>固有时流速涨落</strong>”替换为“<strong>因果序</strong>”——理由是在这一层度规尚未获得定义，$v_{\\tau}$ 无从谈起。</p><p><strong>三处缺陷</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">#</th><th style="text-align:left;">缺陷</th><th style="text-align:left;">展开</th></tr></thead><tbody><tr><td style="text-align:left;">①</td><td style="text-align:left;"><strong>固有时流速不好定义，而引力又恰恰与固有时流速有关</strong></td><td style="text-align:left;">量子引力区（度规未定义）里 $v_{\\tau}=d\\tau/dt$ 无从定义；但引力正落在固有时流速上——FG 因果条件 $v_{\\tau}^{(k)}=\\sqrt{1-\\beta\\delta_v^{(k)}}$（§3.1），GR 侧 $d\\tau/dt=\\sqrt{g_{00}}\\approx1+\\Phi/c^{2}$。→ 把引力所系的那个量换成“因果序”，等于把被解释项替换掉，是生硬的</td></tr><tr><td style="text-align:left;">②</td><td style="text-align:left;"><strong>因果结构的叠加与自组织的层级性不相容</strong></td><td style="text-align:left;">若所有因果结构都叠加，就没有层级；而层级性正是自组织的<strong>内在特征</strong>——群是物质自组织中组织约束的体现（唯物主义群论引言），FG 层级同步算符体系与层级因果断裂皆以此为骨架。说“层级性是退相干之后的产物”可以自辩，但那会使层级性沦为副产品而非自组织的内在结构，并不自然</td></tr><tr><td style="text-align:left;">③</td><td style="text-align:left;"><strong>没有事实依据</strong></td><td style="text-align:left;">上述替换不产生新的可检验输出，也没有观测支持</td></tr></tbody></table><h2 id="三、候选二-禁闭内部只是-qcd" tabindex="-1">三、候选二：禁闭内部只是 QCD <a class="header-anchor" href="#三、候选二-禁闭内部只是-qcd" aria-label="Permalink to &quot;三、候选二：禁闭内部只是 QCD&quot;">​</a></h2><p><strong>内容</strong>：禁闭内部只是 QCD。那个无量纲不确定性关系是 <strong>FG 的</strong>，不是量子引力的；SU(5) 也是物质自组织出来的；在质子／中子诞生之前没有时空，<strong>但物质仍存在内在运动</strong>。</p><p>这一候选把量子引力的内容安放在<strong>物质的内在运动</strong>上，而不是安放在某个已命名的内部结构（因果序的叠加）上：时空与引力是这重内在运动的产物，而 QCD 在时空出现之前就已经是物质自身的运动方式。</p><p><strong>FG 就是 FG</strong>。既然禁闭内部不是量子引力的所在，通常归给量子引力的那部分内容就全部落在 FG 上：无量纲不确定性关系 $\\Delta u\\cdot\\Delta v_{\\tau}\\geq ☯/2$、固有时流速 $v_{\\tau}^{(k)}=\\sqrt{1-\\beta\\delta_v^{(k)}}$、角亏的量子涨落 $\\hat{\\delta}_v^{(1)}$、同步算符的紧化作用，都是 FG 的内容。→ CQM <strong>不另立“量子引力”层</strong>：FG 不是某个更基础层的实现，也不是某个层的别名，它就是这层本身。</p><h2 id="四、候选二的四条后果" tabindex="-1">四、候选二的四条后果 <a class="header-anchor" href="#四、候选二的四条后果" aria-label="Permalink to &quot;四、候选二的四条后果&quot;">​</a></h2><ol><li><strong>引力仍只由质子／中子提供；嘉当矩阵描述的是禁闭边界，不是夸克</strong>。$A_4=\\mathrm{Cartan}(\\mathrm{SU}(5))$ 是<strong>禁闭边界</strong>涌现的代数结构（README 术语表）。夸克不属于禁闭边界层面的物理，故嘉当矩阵给出的结构不落在夸克上；提供引力的仍是质子／中子这一<strong>有限本体</strong>——时空是有限本体之间的关系。</li><li><strong>全息宇宙论依然不一定成立</strong>。禁闭边界与全息原理（AdS/CFT）相关，但全息原理是否成立未知，全息宇宙论是否成立同样未知，框架不采用全息原理。候选二不改变这一判定。</li><li><strong>时空同步依然成立</strong>。时空同步是物质内在运动现实化的一环，不因禁闭内部归为 QCD 而失效；固有时流速与同步条件仍由 FG 侧给出。</li><li><strong>需要改进之处</strong>。候选二把无量纲不确定性关系明确归给 FG，就须把它与 QCD 尺度区分开：$K_L$ 作为耦合空间到物理长度的映射（量纲文档 §6.3.1）属量纲发生学一侧，不是 QCD 的耦合常数；同时“物质在时空之前的内在运动”需要自身的动力学刻画，而不能只由 QCD 的拉格朗日量承担。</li></ol><h2 id="五、两候选对照" tabindex="-1">五、两候选对照 <a class="header-anchor" href="#五、两候选对照" aria-label="Permalink to &quot;五、两候选对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">候选一（禁闭内部＝量子引力）</th><th style="text-align:left;">候选二（禁闭内部＝QCD）</th></tr></thead><tbody><tr><td style="text-align:left;">无量纲不确定性关系</td><td style="text-align:left;">禁闭内部层，读作因果序</td><td style="text-align:left;"><strong>FG 层</strong></td></tr><tr><td style="text-align:left;">固有时流速</td><td style="text-align:left;">该层无从定义，被替换掉</td><td style="text-align:left;">FG 层的量，保留</td></tr><tr><td style="text-align:left;">自组织的层级性</td><td style="text-align:left;">与“全叠加”不相容</td><td style="text-align:left;">保留（自组织的内在结构）</td></tr><tr><td style="text-align:left;">$A_4$ 嘉当矩阵</td><td style="text-align:left;">量子嘉当矩阵 $A_4^{(q)}$</td><td style="text-align:left;">禁闭边界的代数结构</td></tr><tr><td style="text-align:left;">引力来源</td><td style="text-align:left;">禁闭内部</td><td style="text-align:left;">质子／中子（有限本体）</td></tr><tr><td style="text-align:left;">时空同步</td><td style="text-align:left;">退相干后的涌现</td><td style="text-align:left;">物质内在运动的现实化</td></tr><tr><td style="text-align:left;">依据</td><td style="text-align:left;">无事实依据</td><td style="text-align:left;">与既有 FG／同步结构一致</td></tr></tbody></table><h2 id="六、结论" tabindex="-1">六、结论 <a class="header-anchor" href="#六、结论" aria-label="Permalink to &quot;六、结论&quot;">​</a></h2><p>$$\\boxed{\\begin{aligned}&\\text{物质的质是作为其潜在而存在的，不需要质本身叠加涨落；}\\\\\n&\\text{CQM 不另立“量子引力”层：FG 就是 FG；}\\\\&\\text{候选一在固有时流速、层级性、事实依据三处均不成立；}\\\\&\\text{候选二把无量纲不确定性关系归还 FG，保留层级性与时空同步；}\\\\&\\text{引力仍由质子／中子这一有限本体提供，}A_4\\text{ 描述禁闭边界而非夸克；}\\\\\n&\\text{通常归给量子引力的内容由 FG 承担，“量子引力”不设为独立的层。}\\end{aligned}}$$</p><blockquote><p><strong>标注</strong>：【CQM 框架基础】（FG 因果条件 $v_{\\tau}^{(k)}=\\sqrt{1-\\beta\\delta_v^{(k)}}$、$\\Delta u\\cdot\\Delta v_{\\tau}\\geq ☯/2$、SU(5) 由物质自组织锁定、框架不采用全息原理）＋【标准数学／文献】（$A_4=\\mathrm{Cartan}(\\mathrm{SU}(5))$、$[\\hat u,\\hat p_u]=i$、$d\\tau/dt=\\sqrt{g_{00}}$）＋【CQM 构造假设】（两候选的取舍与其后果）。</p></blockquote></div>',1)])])}const f=e(s,[["render",o]]);export{M as __pageData,f as default};
